#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/controls/panel/list_box/list_box_values/list_box_values.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ListBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/list_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// One selected item, or an extended selection with Shift and Ctrl (SelectionMode). Switching to one keeps only the active (or first) selected item and raises selection_changed when that drops others.
template <typename Declaring>
struct ListBoxSelectionModeCapability {
    PropertyCell<ListSelectionMode, ListBoxSelectionModeCapability<Declaring>> selection_mode{ListSelectionMode::one};

    static void assign(ListBoxSelectionModeCapability& capability, ListSelectionMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selection_mode), incoming);
        if (!capability.selection_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selection_mode));
    }
};

// The first visible row (TopIndex); a view onto the list's scroll position. Zero in an empty list; otherwise an index outside the items throws std::out_of_range. Item edits and making a row visible move it.
template <typename Declaring>
struct ListBoxTopIndexCapability {
    PropertyView<std::size_t, ListBoxTopIndexCapability<Declaring>> top_index;

    static void assign(ListBoxTopIndexCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.top_index), std::move(incoming));
    }

    static std::size_t read(const ListBoxTopIndexCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.top_index);
        return current;
    }
};

// The height of each row before text scaling (ItemHeight), 12 to 256 (std::invalid_argument otherwise). coerce_item_height may rewrite a write after that check.
template <typename Declaring>
struct ListBoxItemHeightCapability {
    PropertyCell<double, ListBoxItemHeightCapability<Declaring>> item_height{26.0};

    static void assign(ListBoxItemHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_height), incoming);
        if (!capability.item_height.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_height));
    }
};

// ListSelectionMode as a property value; defined beside ListBox's table.
template <>
struct PropertyValueTraits<ListSelectionMode> {
    static PropertyType type();
    static BindingValue to_binding(ListSelectionMode value);
    static ListSelectionMode from_binding(const BindingValue& value);
};

// Every ListBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct ListBoxCapabilities : public ListBoxSelectionModeCapability<Declaring>,
                             public ListBoxTopIndexCapability<Declaring>,
                             public ListBoxItemHeightCapability<Declaring>,
                             public FontCapability<Declaring> {
    ListBoxCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 12.0, 400, false}) {}
};

} // namespace gui_forms
